class Graph:
    def __init__(self):
        self.graph = {}

    def add_edge(self, u, v):
        if u in self.graph:
            self.graph[u].append(v)
        else:
            self.graph[u] = [v]

    def dfs(self, start, target, visited=None):
        if visited is None:
            visited = set()

        visited.add(start)
        print(f"Visiting node: {start}")

        if start == target:
            print("Target node found! Path: ", end="")
            self.print_path(start, visited)
            return True

        for neighbor in self.graph.get(start, []):
            if neighbor not in visited:
                if self.dfs(neighbor, target, visited):
                    return True

        visited.remove(start)
        return False

    def print_path(self, start, visited):
        if not visited:
            print(start, end="")
        else:
            for node in visited:
                print(f" -> {node}", end="")
            print(f" -> {start}")

